using System;
using System.Linq;
using System.Reflection;
using UnityEditor;
using UnityEngine;
namespace BWVR.Editor {
public static class WindBrushChecks {
 static void Require(bool ok,string why){if(!ok)throw new Exception(why);}
 [MenuItem("BWVR/Verify directional wind fan (Play mode)")]
 public static void Verify(){
  Require(EditorApplication.isPlaying,"Enter Play mode");var palette=UnityEngine.Object.FindAnyObjectByType<GodToolPalette>();var slice=palette.GetComponentInParent<QuestSlice>();var world=slice.GetComponentInChildren<VillageResources>();var weather=slice.GetComponentInChildren<IslandWeather>();var god=slice.GetComponentInChildren<CreatureHybrid>();var nav=slice.GetComponent<IslandNavigation>();var brush=palette.Brush;var flags=BindingFlags.Instance|BindingFlags.NonPublic;var field=typeof(QuestSlice).GetField("state",flags);var original=(SliceState)field.GetValue(slice);god.Interrupt("Wind QA");var test=new SliceState{developmentFocus=true};field.SetValue(slice,test);test.Hybrid.energy=100;world.ResetWorld();
  var blocksField=typeof(WorldBrush).GetField("windBlocks",flags);var ballsField=typeof(WorldBrush).GetField("windBalls",flags);var originalBlocks=(ConstructionBlock[])blocksField.GetValue(brush);var originalBalls=(BeachBall[])ballsField.GetValue(brush);var ball=originalBalls.First();var site=originalBlocks.First().Site;var construction=site.Capture();
  var energyTuning=UnityEngine.Object.FindAnyObjectByType<DivineIntervention>().tuning;bool unlimited=energyTuning.unlimitedEnergy;energyTuning.unlimitedEnergy=false;
  try{
   blocksField.SetValue(brush,Array.Empty<ConstructionBlock>());ballsField.SetValue(brush,new[]{ball});ball.ReturnHome();var point=nav.Terrain.Project(ball.transform.position);var direction=Vector3.forward;var item=ball.GetComponent<CarryItem>();ball.Body.linearVelocity=Vector3.zero;
   var before=ball.Body.linearVelocity;float energy=test.Hybrid.energy;Require(brush.CanWind(point,direction,out _)&&ball.Body.linearVelocity==before&&test.Hybrid.energy==energy,"Wind preview mutated world");Require(brush.WindPulse(point,direction)&&ball.Body.linearVelocity.z>0&&test.Hybrid.energy==energy-WorldBrush.WindCost,"Paid fan did not nudge free ball");energy=test.Hybrid.energy;before=ball.Body.linearVelocity;Require(!brush.WindPulse(point,direction)&&ball.Body.linearVelocity==before&&test.Hybrid.energy==energy,"Same tick stacked impulses");
   test.Hybrid.time+=1;item.held=true;Require(!brush.CanWind(point,direction,out _)&&!brush.WindPulse(point,direction)&&ball.Body.linearVelocity==before,"Wind stole held ball");item.held=false;test.Hybrid.intention.active=true;test.Hybrid.intention.target=ball.StableId;Require(!brush.CanWind(point,direction,out _),"Wind stole creature-reserved ball");test.Hybrid.intention.active=false;
   var peer=slice.GetComponentsInChildren<VillagerExploration>().First();Require(ball.ReservePlay(peer),"Cannot stage villager ball reservation");Require(!brush.CanWind(point,direction,out _),"Wind disturbed reserved social game");ball.CancelRally();
   ball.Body.linearVelocity=new Vector3(0,-12,0);for(int i=0;i<20;i++){test.Hybrid.time+=.3f;brush.WindPulse(point,direction);}Require(new Vector2(ball.Body.linearVelocity.x,ball.Body.linearVelocity.z).magnitude<=WorldBrush.WindSpeedLimit+.001f&&ball.Body.linearVelocity.y==-12,"Wind injected uncontrolled speed/vertical force");
   test.Hybrid.time+=1;ball.Body.linearVelocity=direction*20;before=ball.Body.linearVelocity;Require(brush.WindPulse(point,direction)&&(ball.Body.linearVelocity-before).magnitude<=.851f,"Fan abruptly erased existing projectile momentum");
   ballsField.SetValue(brush,Array.Empty<BeachBall>());var block=site.blocks.First(b=>!b.Item.held&&b.VillagerOwner==null&&site.TryPlan(b,out _,out _));blocksField.SetValue(brush,new[]{block});Require(site.TryPlan(block,out var at,out var rotation)&&site.Drop(block,at,rotation),"Cannot stage snapped block");point=nav.Terrain.Project(block.transform.position);test.Hybrid.time+=1;before=block.Body.linearVelocity;Require(!brush.CanWind(point,direction,out _)&&block.Body.linearVelocity==before,"Wind detached snapped construction");site.Detach(block);block.Body.linearVelocity=Vector3.zero;block.Body.angularVelocity=Vector3.one*10;direction=site.transform.right;
   Require(brush.WindPulse(point,direction)&&block.Body.linearVelocity.x>0&&block.Body.angularVelocity.magnitude<=3.001f,"Loose block did not receive bounded local-frame wind");
   typeof(ConstructionBlock).GetProperty("VillagerOwner").SetValue(block,slice.GetComponentsInChildren<VillagerBlockPlay>().First());before=block.Body.linearVelocity;Require(!brush.CanWind(point,direction,out _)&&block.Body.linearVelocity==before,"Wind stole villager construction");typeof(ConstructionBlock).GetProperty("VillagerOwner").SetValue(block,null);
   test.paused=true;energy=test.Hybrid.energy;Require(!brush.WindPulse(point,direction)&&test.Hybrid.energy==energy,"Paused fan spent energy");test.paused=false;Require(!brush.CanWind(point,Vector3.zero,out _)&&!brush.CanWind(new Vector3(float.NaN,0,0),direction,out _),"Invalid wind accepted");
   test.Hybrid.time+=1;test.Hybrid.energy=1;Require(!brush.ProcessWind(point,direction,true,.05f)&&!brush.Active,"Empty fan retained effects");test.Hybrid.energy=100;Require(!brush.ProcessWind(point,direction,true,.05f),"Held fan auto-restarted after exhaustion");brush.Stop();int pulses=brush.Pulses;energy=test.Hybrid.energy;
   for(int i=0;i<150;i++){test.Hybrid.time+=.05f;block.Body.linearVelocity=Vector3.zero;brush.ProcessWind(point,direction,true,.05f);}Require(brush.Pulses-pulses<=24&&energy-test.Hybrid.energy<=36.001f&&!brush.Active,"Fan stroke exceeded six-second budget");brush.Stop();
   test.Hybrid.time+=1;block.Body.linearVelocity=Vector3.zero;palette.Select(SpiritualTool.WindFan);var ray=new Ray(point+Vector3.up*.2f,Vector3.down);palette.Process(ray,false,true,false,.05f,false);pulses=brush.Pulses;palette.Process(ray,true,true,false,.05f,false);Require(brush.Pulses==pulses+1&&brush.Active,"Palette did not start fan");energy=test.Hybrid.energy;palette.Process(ray,false,true,false,.05f,false);Require(!brush.Active&&test.Hybrid.energy==energy,"Release retained force or spend");
   var copy=JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(test));Require(copy.Valid()&&copy.Hybrid.Evidence.playerMiracles>0&&copy.Hybrid.Evidence.completedCreatureActions==0,"Fan save/attribution invalid");Require(brush.GetComponentsInChildren<ParticleSystem>().Sum(p=>p.main.maxParticles)==96,"Brush particle budget changed");
   energyTuning.unlimitedEnergy=true;test.Hybrid.energy=0;test.Hybrid.time+=1;block.Body.linearVelocity=Vector3.zero;Require(brush.WindPulse(point,direction)&&test.Hybrid.energy==0&&block.Body.linearVelocity.x>0,"Unlimited wind failed at zero balance");test.Hybrid.time+=1;block.Item.held=true;Require(!brush.WindPulse(point,direction),"Unlimited wind stole held block");block.Item.held=false;
   Debug.Log("BWVR_WIND_FAN_PASS: read-only direction/target preview, paid free-ball/loose-block nudges, no stacked pulses, held/snapped/social/creature/villager reservations preserved, bounded horizontal delta/speed with gravity retained, finite/pause gates, exhaustion rearm, six-second budget, palette hold/release, valid player-attributed saves, 96 combined particles");
  }finally{energyTuning.unlimitedEnergy=unlimited;palette.Cancel();brush.Stop();foreach(var b in originalBlocks)if(b!=null&&b.Site==site)typeof(ConstructionBlock).GetProperty("VillagerOwner").SetValue(b,null);site.Restore(construction);ball.ReturnHome();blocksField.SetValue(brush,originalBlocks);ballsField.SetValue(brush,originalBalls);field.SetValue(slice,original);world.ResetWorld();weather.ResetWorld();god.NewSeason();}
 }
}
}
